//#region src/lib/whatsapp/cloud-api.server.ts
/**
* WhatsApp Business Platform (Meta Cloud API). Server only: the access token
* never reaches a browser. Off until WHATSAPP_ACCESS_TOKEN and
* WHATSAPP_PHONE_NUMBER_ID are set as secrets in Lovable Cloud.
*/
var GRAPH = "https://graph.facebook.com/v21.0";
function whatsappKeys() {
	const token = process.env["WHATSAPP_ACCESS_TOKEN"];
	const phoneId = process.env["WHATSAPP_PHONE_NUMBER_ID"];
	return token && phoneId ? {
		token,
		phoneId
	} : null;
}
/**
* Send one approved template message. Marketing messages to guests must use a
* template approved in WhatsApp Manager; {{1}}, {{2}}… in its body are filled
* from bodyParams in order.
*/
async function sendTemplate(keys, input) {
	const body = {
		messaging_product: "whatsapp",
		to: input.to,
		type: "template",
		template: {
			name: input.template,
			language: { code: input.language },
			...input.bodyParams.length ? { components: [{
				type: "body",
				parameters: input.bodyParams.map((text) => ({
					type: "text",
					text: text.slice(0, 200)
				}))
			}] } : {}
		}
	};
	let response;
	try {
		response = await fetch(`${GRAPH}/${encodeURIComponent(keys.phoneId)}/messages`, {
			method: "POST",
			headers: {
				Authorization: `Bearer ${keys.token}`,
				"Content-Type": "application/json"
			},
			body: JSON.stringify(body),
			signal: AbortSignal.timeout(15e3)
		});
	} catch {
		return {
			ok: false,
			error: "Couldn't reach WhatsApp",
			retry: true
		};
	}
	const json = await response.json().catch(() => null);
	if (response.ok && json?.messages?.[0]?.id) return {
		ok: true,
		id: json.messages[0].id
	};
	const code = json?.error?.code;
	const retry = response.status === 429 || response.status >= 500 || code === 130429 || code === 131056;
	return {
		ok: false,
		error: (json?.error?.message ?? `WhatsApp said ${response.status}`).slice(0, 200),
		retry
	};
}
/**
* Send a one-time password with an approved Authentication template (WhatsApp
* requires the code in the body and in the template's copy-code button).
*/
async function sendAuthCode(keys, input) {
	try {
		const response = await fetch(`${GRAPH}/${encodeURIComponent(keys.phoneId)}/messages`, {
			method: "POST",
			headers: {
				Authorization: `Bearer ${keys.token}`,
				"Content-Type": "application/json"
			},
			body: JSON.stringify({
				messaging_product: "whatsapp",
				to: input.to,
				type: "template",
				template: {
					name: input.template,
					language: { code: input.language },
					components: [{
						type: "body",
						parameters: [{
							type: "text",
							text: input.code
						}]
					}, {
						type: "button",
						sub_type: "url",
						index: "0",
						parameters: [{
							type: "text",
							text: input.code
						}]
					}]
				}
			}),
			signal: AbortSignal.timeout(15e3)
		});
		const json = await response.json().catch(() => null);
		if (response.ok && json?.messages?.[0]?.id) return {
			ok: true,
			id: json.messages[0].id
		};
		return {
			ok: false,
			error: (json?.error?.message ?? `WhatsApp said ${response.status}`).slice(0, 200),
			retry: response.status >= 500
		};
	} catch {
		return {
			ok: false,
			error: "Couldn't reach WhatsApp",
			retry: true
		};
	}
}
//#endregion
export { sendTemplate as n, whatsappKeys as r, sendAuthCode as t };
